import React, { useEffect, useState } from 'react'
import useWebSocket, { ReadyState } from "react-use-websocket";
import { getAccessToken } from "../../helpers/authUtils";
import { useParams } from "react-router-dom";
import { ChatMessage } from "../../components/chat/ChatMessage";
export default function Chat() {
  const [welcomeMessage, setWelcomeMessage] = useState("");
  const [messageHistory, setMessageHistory] = useState([]);
  const [message, setMessage] = useState("");
  const [name, setName] = useState("");
  const [user, setUser] = useState();
  const [userToken, setUserToken] = useState();
  const { conversationName } = useParams(); // add this
  // const [param, setparam] = useState("254722217348__254722217349")
  console.log("wefvscbg", conversationName);

  useEffect(() => {
    setUserToken(getAccessToken());
  }, []);

  const { readyState, sendJsonMessage } = useWebSocket(
    userToken ? `ws://127.0.0.1:8000/ws/chats/${conversationName}/` : null,
    {
      queryParams: {
        token: userToken ? userToken : "",
      },

      onOpen: () => {
        console.log("Connected!");
      },
      onClose: () => {
        console.log("Disconnected!");
      },

      // New onMessage handler
      onMessage: (e) => {
        const data = JSON.parse(e.data);
        console.log("data..", data);
        switch (data.type) {
          case "welcome_message":
            setWelcomeMessage(data.message);
            break;
          case "greeting_response":
            setWelcomeMessage(data.message);
            break;
          case "chat_message_echo":
            setMessageHistory((prev) => prev.concat(data.message));
            break;
          case "last_50_messages":
            setMessageHistory(data.messages);
            break;
          default:
            console.log("Unknown message type!");
            break;
        }
      },
    }
  );

  const connectionStatus = {
    [ReadyState.CONNECTING]: "Connecting",
    [ReadyState.OPEN]: "Open",
    [ReadyState.CLOSING]: "Closing",
    [ReadyState.CLOSED]: "Closed",
    [ReadyState.UNINSTANTIATED]: "Uninstantiated",
  }[readyState];

  function handleChangeMessage(e: any) {
    setMessage(e.target.value);
  }

  function handleChangeName(e: any) {
    setName(e.target.value);
  }

  function handleSubmit() {
    sendJsonMessage({
      type: "chat_message",
      message,
      name,
    });
    setName("");
    setMessage("");
  }

  return (
    <div>
      <span>The WebSocket is currently {connectionStatus}</span>
      <p>{welcomeMessage}</p>
      <input
        name="name"
        placeholder="Name"
        onChange={handleChangeName}
        value={name}
        className="shadow-sm sm:text-sm border-gray-300 bg-gray-100 rounded-md"
      />
      <input
        name="message"
        placeholder="Message"
        onChange={handleChangeMessage}
        value={message}
        className="ml-2 shadow-sm sm:text-sm border-gray-300 bg-gray-100 rounded-md"
      />
      <button className="ml-3 bg-gray-300 px-3 py-1" onClick={handleSubmit}>
        Submit
      </button>
      <hr />
      <ul className="mt-3 flex flex-col-reverse relative w-full border border-gray-200 overflow-y-auto p-6">
        {messageHistory &&
          messageHistory.length &&
          messageHistory.map((message, index) => (
            <div className="border border-gray-200 py-3 px-3" key={index}>
              {message ? (
                <ChatMessage key={message.id} message={message} />
              ) : (
                <div></div>
              )}
            </div>
          ))}
      </ul>
    </div>
  );
}
