
import { useEffect, useState } from "react";
import { getLoggedInUser } from "../../helpers/authUtils";

export function classNames(...classes: any) {
  return classes.filter(Boolean).join(" ");
}

export function ChatMessage({ message }) {
  const [user, setuser] = useState(getLoggedInUser());

  console.log("message at ChatMessage", message);
  console.log("user at ChatMessage", user);

  function formatMessageTimestamp(timestamp) {
    const date = new Date(timestamp);
    return date.toLocaleTimeString().slice(0, 5);
  }
  const [fromMe, setfromMe] = useState(
    user && message ? user.user_id === message.from_user.id : false
  );

  useEffect(() => {
    console.log(user.user_id, message.from_user.id);
    console.log("from to", user.user_id === message.from_user.id);
    console.log(user.user_id, typeof user.user_id);
    if (message && user) {
      console.log("type of msg id", typeof message.from_user.id);
      console.log("type of user id", typeof user.user_id);
      // setfromMe(user && user.user_id === message && message.from_user.id);
    }
  }, [message, user]);
  useEffect(() => {
    console.log("from me", fromMe);
  }, [fromMe]);
  return (
    <li
      className={classNames(
        "mt-1 mb-1 flex",
        user && message && user.user_id === message.to_user.id
          ? "justify-start"
          : "justify-end"
      )}
    >
      <div
        className={classNames(
          "relative max-w-xl rounded-lg px-2 py-1 text-gray-700 shadow",
          user && user.user_id === message.to_user.id ? "" : "bg-gray-100"
        )}
      >
        <div className="flex items-end">
          <span className="block">{message.content}</span>
          <span
            className="ml-2"
            style={{
              fontSize: "0.6rem",
              lineHeight: "1rem",
            }}
          >
            {formatMessageTimestamp(message.timestamp)}
          </span>
        </div>
      </div>
    </li>
  );
}